using System;using System.Collections.Generic;using System.IO;using System.Text;namespace Mapping{    /// <summary>    /// BI ? DI ? Mapping    /// </summary>    public class BYDConverter : MapConverterSkeleton    {        static BYDConverter()        {            MapConverterMap.LookupWithDefault("BYD", new BYDConverter());        }        private BinCode[,,,] OriginalBinCodes { get; set; }        /// <summary>        ///         /// </summary>        public BYDConverter()        {        }        /// <summary>        ///         /// </summary>        /// <param name="mapFile"></param>        /// <returns></returns>        public override MapData Read(string mapFile, bool isOriginalMap)        {            if (string.IsNullOrWhiteSpace(mapFile))            {                throw new ArgumentNullException(nameof(mapFile));            }            var index = mapFile.LastIndexOf('.') + 1;            var fileType = mapFile.Substring(index);            using (FileStream fs = new FileStream(mapFile, FileMode.Open, FileAccess.Read))            {                using (StreamReader sr = new StreamReader(fs, Encoding.Default))                {                    if (fileType.Equals("txt"))                    {                        var md = this.ReadTxt(sr, isOriginalMap);                        md.SubstrateID = Path.GetFileNameWithoutExtension(mapFile);                        return md;                    }                    else                    {                        var md = this.ReadMap(sr, isOriginalMap);                        md.SubstrateID = Path.GetFileNameWithoutExtension(mapFile);                        return md;                    }                }            }        }        /// <summary>        ///         /// </summary>        /// <param name="map"></param>        /// <param name="fileName"></param>        public override void Save(Map map, string fileName)        {            if (string.IsNullOrWhiteSpace(fileName))            {                throw new ArgumentNullException(nameof(fileName));            }            var index = fileName.LastIndexOf('.') + 1;            var fileType = fileName.Substring(index);            using (FileStream fs = new FileStream(Path.GetFullPath(fileName), FileMode.OpenOrCreate, FileAccess.ReadWrite))            {                using (StreamWriter sw = new StreamWriter(fs, Encoding.Default))                {                    if (fileType.Equals("txt"))                    {                        SaveTxt(map, sw);                    }                    else                    {                        SaveMap(map, sw);                    }                }            }        }        private MapData ReadTxt(StreamReader sr, bool isOriginalMap)        {            var mapData = new MapData();            // FAB ID            var line = sr.ReadLine();            // FAB PRODUCT ID            line = sr.ReadLine();            // FAB LOT ID            line = sr.ReadLine();            // CP VENDOR ID            line = sr.ReadLine();            // CUSTOMER PRODUCT ID            line = sr.ReadLine();            // CUSTOMER LOT ID            line = sr.ReadLine();            // WAFER ID            line = sr.ReadLine();            // OCR ID            line = sr.ReadLine();            // GROSS DIE            line = sr.ReadLine();            // PASS DIE            line = sr.ReadLine();            // INKLESS NOTCH            line = sr.ReadLine();            // XINCREAMENT            line = sr.ReadLine();            // YINCREAMENT            line = sr.ReadLine();            // Null Bin            mapData.NullBin = Bin.CreateNullBin('.');            // BinInformation            mapData.Bins = new BinCollection();            //var bin = new Bin(new BinCode('0'), false);            //mapData.Bins.Add(bin);            //bin = new Bin(new BinCode('1'), true);            //mapData.Bins.Add(bin);            int rows = 0;            int columns = 0;            var binCodes = new List<List<char>>();            do            {                line = sr.ReadLine();                if (line == "[WorkingMap]" && !isOriginalMap)                {                    rows = 0;                    columns = 0;                    binCodes = new List<List<char>>();                    continue;                }                if (line is null || (line == "[WorkingMap]" && isOriginalMap))                {                    break;                }                if (string.IsNullOrWhiteSpace(line))                {                    continue;                }                if (string.Compare(line.Trim(), "INKLESS_START", true) == 0)                {                    continue;                }                rows++;                columns = 0;                var codes = new List<char>();                foreach (var ch in line.Trim())                {                    columns++;                    codes.Add(ch);                    //if ((ch != 'X') && (!mapData.Bins.Exists(b => b.Code == ch)))                    //{                    //    var work = ch == '1' ? true : false;                    //    var bin = new Bin(new BinCode(ch), work);                    //    mapData.Bins.Add(bin);                    //}                }                binCodes.Add(codes);            } while (true);            mapData.Rows = rows;            mapData.Columns = columns;            // BinCode            mapData.BinCodes = new BinCode[1, 1, mapData.Rows, mapData.Columns];            int r = 0, c = 0;            foreach (var codes in binCodes)            {                c = 0;                foreach (var cs in codes)                {                    mapData.BinCodes[0, 0, r, c] = cs;                    c++;                    var binCode = new BinCode(cs);                    var bin = new Bin(binCode, true);                    var foundBin = mapData.Bins.Find(x => x.Code == binCode);                    if ((foundBin is null) && binCode != mapData.NullBin.Code)                    {                        mapData.Bins.Add(bin);                    }                }                r++;            }            if (isOriginalMap)                OriginalBinCodes = mapData.BinCodes;            return mapData;        }        private MapData ReadMap(StreamReader sr, bool isOriginalMap)        {            var mapData = new MapData();            // FAB ID            var line = sr.ReadLine();            // FAB PRODUCT ID            line = sr.ReadLine();            // FAB LOT ID            line = sr.ReadLine();            // CP VENDOR ID            line = sr.ReadLine();            // CUSTOMER ID            line = sr.ReadLine();            // CUSTOMER PRODUCT ID            line = sr.ReadLine();            // CUSTOMER LOT ID            line = sr.ReadLine();            // WAFER ID            line = sr.ReadLine();            // OCR ID            line = sr.ReadLine();            // Date            line = sr.ReadLine();            // GROSS DIE            line = sr.ReadLine();            // PASS DIE            line = sr.ReadLine();            // INKLESS NOTCH            line = sr.ReadLine();            // XINCREAMENT            line = sr.ReadLine();            // YINCREAMENT            line = sr.ReadLine();            // Null Bin            mapData.NullBin = Bin.CreateNullBin('.');            // BinInformation            mapData.Bins = new BinCollection();            //var bin = new Bin(new BinCode('0'), false);            //mapData.Bins.Add(bin);            //bin = new Bin(new BinCode('1'), true);            //mapData.Bins.Add(bin);            int rows = 0;            int columns = 0;            var binCodes = new List<List<char>>();            do            {                line = sr.ReadLine();                if (line == "[WorkingMap]" && !isOriginalMap)                {                    rows = 0;                    columns = 0;                    binCodes = new List<List<char>>();                    continue;                }                if (line is null || (line == "[WorkingMap]" && isOriginalMap))                {                    break;                }                if (string.IsNullOrWhiteSpace(line))                {                    continue;                }                if (string.Compare(line.Trim(), "INKLESS_START", true) == 0)                {                    continue;                }                rows++;                columns = 0;                var codes = new List<char>();                foreach (var ch in line.Trim())                {                    columns++;                    codes.Add(ch);                    //if ((ch != 'X') && (!mapData.Bins.Exists(b => b.Code == ch)))                    //{                    //    var work = ch == '1' ? true : false;                    //    var bin = new Bin(new BinCode(ch), work);                    //    mapData.Bins.Add(bin);                    //}                }                binCodes.Add(codes);            } while (true);            mapData.Rows = rows;            mapData.Columns = columns;            // BinCode            mapData.BinCodes = new BinCode[1, 1, mapData.Rows, mapData.Columns];            int r = 0, c = 0;            foreach (var codes in binCodes)            {                c = 0;                foreach (var cs in codes)                {                    mapData.BinCodes[0, 0, r, c] = cs;                    c++;                    var binCode = new BinCode(cs);                    var bin = new Bin(binCode, true);                    var foundBin = mapData.Bins.Find(x => x.Code == binCode);                    if ((foundBin is null) && binCode != mapData.NullBin.Code)                    {                        mapData.Bins.Add(bin);                    }                }                r++;            }            if (isOriginalMap)                OriginalBinCodes = mapData.BinCodes;            return mapData;        }        private void SaveTxt(Map map, StreamWriter sw)        {            int sum = map.Count();            int goodCount = map.Count(UnitState.Good);            int pickedCount = map.CountPicked();            sw.WriteLine("FAB ID              : F001");            sw.WriteLine("FAB PRODUCT ID      : HPW011A");            sw.WriteLine("FAB LOT ID          : FA2Y-8902");            sw.WriteLine("CP VENDOR ID        : F001");            sw.WriteLine("CUSTOMER PRODUCT ID : HPW011A");            sw.WriteLine("CUSTOMER LOT ID     : FA2Y-8902");            sw.WriteLine("WAFER ID            : 24");            sw.WriteLine("OCR ID              : FA2Y-8902-24");            sw.WriteLine("GROSS DIE           : 627");            sw.WriteLine("PASS DIE            : 591");            sw.WriteLine("INKLESS NOTCH       : DOWN");            sw.WriteLine("XINCREAMENT         : RIGHT");            sw.WriteLine("YINCREAMENT         : DOWN");            sw.WriteLine();            sw.WriteLine();            sw.WriteLine();            for (int i = 0; i < map.Rows; i++)            {                StringBuilder builder = new StringBuilder();                for (int j = 0; j < map.Columns; j++)                {                    var unit = OriginalBinCodes[0, 0, i, j];                    builder.Append(unit.FormattedCode);                }                sw.WriteLine(builder.ToString());            }            sw.WriteLine("[WorkingMap]");            for (int i = 0; i < map.Rows; i++)            {                StringBuilder builder = new StringBuilder();                for (int j = 0; j < map.Columns; j++)                {                    string binCode = ".";                    var unit = map[i, j];                    if (unit.Bin == map.NullBin)                    {                        binCode = ".";                    }                    else if (unit.State == UnitState.Picked || unit.State == UnitState.Processed)                    {                        binCode = "@";                    }                    else if (unit.State == UnitState.Reject)                    {                        binCode = "&";                    }                    else                    {                        binCode = unit.Bin.FormattedCode;                    }                    builder.Append(binCode);                }                sw.WriteLine(builder.ToString());            }        }        private void SaveMap(Map map, StreamWriter sw)        {            int sum = map.Count();            int goodCount = map.Count(UnitState.Good);            int pickedCount = map.CountPicked();            sw.WriteLine("FAB ID              : 45704");            sw.WriteLine("FAB PRODUCT ID      : Hi7B81CHV100WHS");            sw.WriteLine("FAB LOT ID          : FA31-8886");            sw.WriteLine("CP VENDOR ID        : 45704");            sw.WriteLine("CUSTOMER ID         : 359");            sw.WriteLine("CUSTOMER PRODUCT ID : Hi7B81CHV100WHS");            sw.WriteLine("CUSTOMER LOT ID     : FA31-8886");            sw.WriteLine("WAFER ID            : 04");            sw.WriteLine("OCR ID              : FA31-8886-04");            sw.WriteLine("DATE                : 2023/2/24 22:31:15");            sw.WriteLine("GROSS DIE           : 627");            sw.WriteLine("PASS DIE            : 607");            sw.WriteLine("INKLESS NOTCH       : DOWN");            sw.WriteLine("XINCREAMENT         : RIGHT");            sw.WriteLine("YINCREAMENT         : DOWN");            sw.WriteLine();            sw.WriteLine();            sw.WriteLine();            for (int i = 0; i < map.Rows; i++)            {                StringBuilder builder = new StringBuilder();                for (int j = 0; j < map.Columns; j++)                {                    var unit = OriginalBinCodes[0, 0, i, j];                    builder.Append(unit.FormattedCode);                }                sw.WriteLine(builder.ToString());            }            sw.WriteLine("[WorkingMap]");            for (int i = 0; i < map.Rows; i++)            {                StringBuilder builder = new StringBuilder();                for (int j = 0; j < map.Columns; j++)                {                    string binCode = ".";                    var unit = map[i, j];                    if (unit.Bin == map.NullBin)                    {                        binCode = ".";                    }                    else if (unit.State == UnitState.Picked || unit.State == UnitState.Processed)                    {                        binCode = "@";                    }                    else if (unit.State == UnitState.Reject)                    {                        binCode = "&";                    }                    else                    {                        binCode = unit.Bin.FormattedCode;                    }                    builder.Append(binCode);                }                sw.WriteLine(builder.ToString());            }        }    }}